package presentation;

import business.UserBUS;
import business.PCBUS;
import business.FoodBUS;
import entity.Food;
import entity.User;
import entity.PC;
import util.DatabaseConnection;

import java.util.Scanner;
import java.sql.*;

public class Main {

    static Scanner sc = new Scanner(System.in);
    static UserBUS userBUS = new UserBUS();
    static PCBUS pcBUS = new PCBUS();
    static FoodBUS foodBUS = new FoodBUS();
    static String currentUsername = ""; // Lưu username hiện tại

    public static void main(String[] args) {

        System.out.println("Starting Cyber Cafe Management System...");

        while (true) {

            System.out.println("\n===== HỆ THỐNG QUẢN LÝ PHÒNG NET =====");
            System.out.println("1. Đăng ký tài khoản");
            System.out.println("2. Đăng nhập");
            System.out.println("0. Thoát");

            System.out.print("Lựa chọn của bạn: ");

            try {

                int choice = Integer.parseInt(sc.nextLine());

                switch (choice) {

                    case 1:
                        register();
                        break;

                    case 2:
                        login();
                        break;

                    case 0:
                        System.out.println("Thoát chương trình...");
                        System.exit(0);

                    default:
                        System.out.println("Lựa chọn không hợp lệ!");
                }

            } catch (Exception e) {
                System.out.println("Vui lòng nhập số!");
                e.printStackTrace();
            }
        }
    }

    // ========================
    // ĐĂNG KÝ
    // ========================

    public static void register() {

        System.out.println("\n===== ĐĂNG KÝ TÀI KHOẢN =====");

        System.out.print("Nhập username: ");
        String username = sc.nextLine().trim();

        System.out.print("Nhập password: ");
        String password = sc.nextLine().trim();

        // Validation
        if(username.isEmpty() || password.isEmpty()){
            System.out.println("Username và password không được để trống!");
            return;
        }

        // Mặc định role là CUSTOMER
        User user = new User(username, password, "CUSTOMER");

        userBUS.register(user);
    }

    // ========================
    // ĐĂNG NHẬP
    // ========================

    public static void login() {

        System.out.println("\n===== ĐĂNG NHẬP =====");

        System.out.print("Username: ");
        String username = sc.nextLine();

        System.out.print("Password: ");
        String password = sc.nextLine();

        String role = userBUS.login(username, password);

        if (role == null) {

            System.out.println("Đăng nhập thất bại!");

        } else {

            System.out.println("Đăng nhập thành công!");

            currentUsername = username; // Lưu username hiện tại

            role = role.toUpperCase();

            if(role.equals("ADMIN")){
                adminMenu();
            }
            else if(role.equals("STAFF")){
                staffMenu();
            }
            else if(role.equals("CUSTOMER")){
                customerMenu();
            }
            else{
                System.out.println("Lỗi: Quyền không hợp lệ! Chỉ chấp nhận ADMIN, STAFF hoặc CUSTOMER");
            }
        }
    }

    // ========================
    // MENU ADMIN
    // ========================

    public static void adminMenu() {

        while (true) {

            System.out.println("\n===== MENU QUẢN TRỊ =====");
            System.out.println("1. Thêm máy PC");
            System.out.println("2. Hiển thị danh sách PC");
            System.out.println("3. Hiển thị danh sách người dùng");
            System.out.println("4. Cập nhật quyền người dùng");
            System.out.println("5. Thêm dịch vụ");
            System.out.println("6. Hiển thị dịch vụ");
            System.out.println("7. Xoá máy PC");
            System.out.println("8. Xoá người dùng");
            System.out.println("9. Xoá dịch vụ");
            System.out.println("10. Xác nhận khách hàng đã nhận máy");
            System.out.println("0. Đăng xuất");

            System.out.print("Lựa chọn của bạn: ");

            try {

                int choice = Integer.parseInt(sc.nextLine());

                switch (choice) {

                    case 1:

                        System.out.print("Nhập tên PC: ");
                        String name = sc.nextLine().trim();

                        String status = "AVAILABLE";

                        System.out.print("Nhập giá mỗi giờ: ");
                        double price = Double.parseDouble(sc.nextLine());

                        // Validation
                        if(name.isEmpty()){
                            System.out.println("Tên PC không được để trống!");
                            break;
                        }

                        if(price <= 0){
                            System.out.println("Giá mỗi giờ không được bằng hoặc nhỏ hơn 0!");
                            break;
                        }

                        PC pc = new PC(name, status, price);

                        pcBUS.addPC(pc);

                        break;
                    case 2:
                        pcBUS.showPC();
                        break;

                    case 3:
                        userBUS.showUsers();
                        break;

                    case 4:

                        System.out.print("Nhập username cần đổi quyền: ");
                        String username = sc.nextLine().trim();

                        System.out.print("Nhập quyền mới (ADMIN/STAFF/CUSTOMER): ");
                        String role = sc.nextLine().trim().toUpperCase();

                        // Validation
                        if(!role.equals("ADMIN") && !role.equals("STAFF") && !role.equals("CUSTOMER")){
                            System.out.println("Quyền không hợp lệ! Vui lòng nhập: ADMIN, STAFF hoặc CUSTOMER");
                            break;
                        }

                        userBUS.updateRole(username, role);

                        break;
                    case 5:

                        System.out.print("Tên dịch vụ: ");
                        String foodName = sc.nextLine().trim();

                        System.out.print("Giá: ");
                        double foodPrice = Double.parseDouble(sc.nextLine());

                        System.out.print("Số lượng: ");
                        int stock = Integer.parseInt(sc.nextLine());

                        System.out.print("Mô tả: ");
                        String des = sc.nextLine().trim();

                        // Validation
                        if(foodName.isEmpty()){
                            System.out.println("Tên dịch vụ không được để trống!");
                            break;
                        }

                        if(foodPrice <= 0){
                            System.out.println("Giá không được bằng hoặc nhỏ hơn 0!");
                            break;
                        }

                        if(stock <= 0){
                            System.out.println("Số lượng không được bằng hoặc nhỏ hơn 0!");
                            break;
                        }

                        Food food = new Food(foodName, foodPrice, stock, des);

                        foodBUS.addFood(food);

                        break;

                    case 6:
                        foodBUS.showFoods();
                        break;
                    case 7:
                        pcBUS.showPC();
                        System.out.print("Nhập ID PC muốn xoá: ");
                        int pcId = Integer.parseInt(sc.nextLine());
                        pcBUS.deletePC(pcId);
                        break;
                    case 8:
                        userBUS.showUsers();
                        System.out.print("Nhập username muốn xoá: ");
                        String userToDelete = sc.nextLine().trim();
                        userBUS.deleteUser(userToDelete);
                        break;
                    case 9:
                        foodBUS.showFoods();
                        System.out.print("Nhập ID dịch vụ muốn xoá: ");
                        int foodId = Integer.parseInt(sc.nextLine());
                        foodBUS.deleteFood(foodId);
                        break;
                    case 10:
                        // Xác nhận khách hàng đã nhận máy
                        pcBUS.showActivePCSessions();
                        System.out.print("Nhập ID phiên PC: ");
                        int sessionId = Integer.parseInt(sc.nextLine());
                        pcBUS.confirmPCReceived(sessionId);
                        break;
                    case 0:
                        System.out.println("Đăng xuất");
                        return;

                    default:
                        System.out.println("Lựa chọn không hợp lệ!");
                }

            } catch (Exception e) {
                System.out.println("Vui lòng nhập đúng định dạng!");
            }
        }
    }

    // ========================
    // MENU CUSTOMER
    // ========================

    public static void customerMenu(){

        while(true){

            System.out.println("\n===== MENU KHÁCH HÀNG =====");
            System.out.println("1. Xem danh sách PC");
            System.out.println("2. Sử dụng PC");
            System.out.println("3. Xem menu đồ ăn");
            System.out.println("4. Xem số dư tài khoản");
            System.out.println("5. Lịch sử giao dịch");
            System.out.println("6. Báo cáo tổng quát");
            System.out.println("7. Nạp tiền vào tài khoản");
            System.out.println("0. Đăng xuất");

            System.out.print("Lựa chọn của bạn: ");

            try{

                int choice = Integer.parseInt(sc.nextLine());

                switch(choice){

                    case 1:
                        pcBUS.showPC();
                        break;

                    case 2:

                        pcBUS.showPC();

                        System.out.print("Nhập ID PC muốn sử dụng: ");
                        int id = Integer.parseInt(sc.nextLine());

                        pcBUS.startPC(id, currentUsername);
                        break;

                    case 3:
                        foodBUS.showFoods();
                        break;

                    case 4:
                        // Hiển thị số dư
                        userBUS.showBalance(currentUsername);
                        break;

                    case 5:
                        // Lịch sử giao dịch
                        userBUS.showTransactionHistory(currentUsername);
                        break;

                    case 6:
                        // Báo cáo tổng quát
                        showGeneralReport(currentUsername);
                        break;

                    case 7:
                        // Nạp tiền vào tài khoản
                        System.out.print("Nhập số tiền muốn nạp: ");
                        double amount = Double.parseDouble(sc.nextLine());

                        // Validation
                        if(amount <= 0){
                            System.out.println("Số tiền phải lớn hơn 0!");
                            break;
                        }

                        userBUS.depositMoney(currentUsername, amount);

                        break;

                    case 0:
                        System.out.println("Đăng xuất");
                        return;

                    default:
                        System.out.println("Lựa chọn không hợp lệ!");
                }

            }catch(Exception e){
                System.out.println("Vui lòng nhập số!");
            }
        }
    }

    // ========================
    // MENU STAFF
    // ========================

    public static void staffMenu(){

        while(true){

            System.out.println("\n===== MENU NHÂN VIÊN =====");
            System.out.println("1. Xem danh sách PC");
            System.out.println("2. Cập nhật trạng thái PC");
            System.out.println("3. Xem đơn dịch vụ");
            System.out.println("4. Nạp tiền cho khách hàng");
            System.out.println("5. Xem báo cáo hệ thống");
            System.out.println("0. Đăng xuất");

            System.out.print("Lựa chọn: ");

            try{

                int choice = Integer.parseInt(sc.nextLine());

                switch(choice){

                    case 1:
                        pcBUS.showPC();
                        break;

                    case 2:

                        pcBUS.showPC();

                        System.out.print("Nhập ID PC: ");
                        int id = Integer.parseInt(sc.nextLine());

                        System.out.print("Trạng thái (AVAILABLE/BUSY/MAINTENANCE): ");
                        String status = sc.nextLine().trim().toUpperCase();

                        // Validation
                        if(!status.equals("AVAILABLE") && !status.equals("BUSY") && !status.equals("MAINTENANCE")){
                            System.out.println("Trạng thái không hợp lệ! Vui lòng nhập: AVAILABLE, BUSY hoặc MAINTENANCE");
                            break;
                        }

                        pcBUS.updateStatus(id, status);

                        break;

                    case 3:
                        foodBUS.showFoods();
                        break;

                    case 4:
                        System.out.print("Nhập username khách hàng: ");
                        String username = sc.nextLine().trim();

                        System.out.print("Nhập số tiền muốn nạp: ");
                        double amount = Double.parseDouble(sc.nextLine());

                        // Validation
                        if(amount <= 0){
                            System.out.println("Số tiền phải lớn hơn 0!");
                            break;
                        }

                        userBUS.recharge(username, amount);

                        break;

                    case 5:
                        // Xem báo cáo hệ thống
                        showSystemReport();
                        break;

                    case 0:
                        System.out.println("Đăng xuất");
                        return;

                    default:
                        System.out.println("Lựa chọn không hợp lệ");
                }

            }catch(Exception e){
                System.out.println("Nhập sai định dạng!");
            }
        }
    }

    // ========================
    // BÁO CÁO TỔNG QUÁT
    // ========================

    public static void showGeneralReport(String username) {
        System.out.println("\n===== BÁO CÁO TỔNG QUÁT =====");
        System.out.println("Người dùng: " + username);

        // Hiển thị số dư
        userBUS.showBalance(username);

        // Thống kê giao dịch
        try {
            int userId = userBUS.getUserIdByUsername(username);
            Connection conn = DatabaseConnection.getConnection();

            // Tổng số giao dịch
            String countQuery = "SELECT COUNT(*) as total FROM transactions WHERE user_id = ?";
            PreparedStatement psCount = conn.prepareStatement(countQuery);
            psCount.setInt(1, userId);
            ResultSet rsCount = psCount.executeQuery();
            int totalTransactions = rsCount.next() ? rsCount.getInt("total") : 0;

            // Tổng tiền đã chi tiêu
            String sumQuery = "SELECT SUM(CASE WHEN amount < 0 THEN ABS(amount) ELSE 0 END) as total_spent FROM transactions WHERE user_id = ?";
            PreparedStatement psSum = conn.prepareStatement(sumQuery);
            psSum.setInt(1, userId);
            ResultSet rsSum = psSum.executeQuery();
            double totalSpent = rsSum.next() ? rsSum.getDouble("total_spent") : 0.0;

            // Tổng tiền đã nạp
            String depositQuery = "SELECT SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END) as total_deposit FROM transactions WHERE user_id = ?";
            PreparedStatement psDeposit = conn.prepareStatement(depositQuery);
            psDeposit.setInt(1, userId);
            ResultSet rsDeposit = psDeposit.executeQuery();
            double totalDeposit = rsDeposit.next() ? rsDeposit.getDouble("total_deposit") : 0.0;

            System.out.println("Tổng số giao dịch: " + totalTransactions);
            System.out.println("Tổng tiền đ�� nạp: " + String.format("%.0f", totalDeposit) + " VND");
            System.out.println("Tổng tiền đã chi tiêu: " + String.format("%.0f", totalSpent) + " VND");

        } catch (Exception e) {
            System.out.println("Lỗi khi tạo báo cáo!");
            e.printStackTrace();
        }
    }

    // ========================
    // BÁO CÁO HỆ THỐNG CHO STAFF
    // ========================

    public static void showSystemReport() {
        System.out.println("\n===== BÁO CÁO HỆ THỐNG =====");

        // Thống kê số lượng PC theo trạng thái
        pcBUS.countPCByStatus();

        // Thống kê doanh thu theo ngày
        try {
            Connection conn = DatabaseConnection.getConnection();

            String query = "SELECT DATE(created_at) as date, SUM(amount) as total_income " +
                           "FROM transactions " +
                           "WHERE amount > 0 " +
                           "GROUP BY DATE(created_at) " +
                           "ORDER BY DATE(created_at) DESC";

            PreparedStatement ps = conn.prepareStatement(query);
            ResultSet rs = ps.executeQuery();

            System.out.println("\nDoanh thu theo ngày:");
            while(rs.next()) {
                Date date = rs.getDate("date");
                double totalIncome = rs.getDouble("total_income");
                System.out.println("Ngày: " + date + ", Doanh thu: " + totalIncome + " VND");
            }

        } catch (Exception e) {
            System.out.println("Lỗi khi tạo báo cáo hệ thống!");
            e.printStackTrace();
        }
    }
}

