                        // Quản lý số dư tài khoản
                        System.out.println("1. Xem số dư tất cả người dùng");
                        System.out.println("2. Cập nhật số dư người dùng");
                        System.out.println("0. Quay lại");

                        System.out.print("Lựa chọn của bạn: ");

                        int subChoice = Integer.parseInt(sc.nextLine());

                        switch (subChoice) {
                            case 1:
                                // Xem số dư tất cả người dùng
                                userBUS.showAllBalances();
                                break;
                            case 2:
                                // Cập nhật số dư người dùng
                                System.out.print("Nhập username người dùng: ");
                                String usernameToUpdate = sc.nextLine().trim();

                                System.out.print("Nhập số dư mới: ");
                                double newBalance = Double.parseDouble(sc.nextLine());

                                userBUS.updateBalance(usernameToUpdate, newBalance);
                                break;
                            case 0:
                                break;
                            default:
                                System.out.println("Lựa chọn không hợp lệ!");
                        }

                        break;
                    case 0:
                        System.out.println("Đăng xuất");
                        return;

                    default:
                        System.out.println("Lựa chọn không hợp lệ!");
                }

            } catch (Exception e) {
                System.out.println("Vui lòng nhập đúng định dạng!");
            }
        }
    }

